import { useEffect, useState } from 'react';
import axios from 'axios';
function VideoSection ({setIndicator}) {
    const [slide, setSlide] = useState([]);

    useEffect(() => {
        setIndicator(true)
        const fetchSlides = async () => {
            try {
                // Use a CORS proxy service to bypass CORS restrictions during development
                const response = await axios.get('http://localhost:5000/images');
                setSlide(response.data?.[0].GalleryPhoto?.filter((ele) => ele.isActive === true)?.[0]);
                console.log(response.data?.[0].GalleryPhoto?.filter((ele) => ele.isActive === true)?.[0])
                setIndicator(false)
            } catch (error) {
                setIndicator(false)
                console.error('Error fetching images section content:', error);
            }
        };
        fetchSlides();
    }, []);
    return (
        <>
            <div style={{maxWidth: "99%",height: "832px", position: "relative",left: ".5%", top: "148px"}}> 
                <img style={{width :'100%', height :'100%'}} src={slide?.url} alt='big' />
            </div>
        </>
    )
}

export default VideoSection;
